import { CommonModule } from '@angular/common';
import {
    Component,
    computed,
    effect,
    inject,
    input,
    OnInit,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { MatTooltipModule } from '@angular/material/tooltip';
import {
    AsyncHandler,
    Booking,
    BOOKING_TYPE_COLORS,
    CalendarEvent,
    OrganisationService,
    SettingsService,
} from '@placeos/common';
import {
    IconComponent,
    SettingsToggleComponent,
    TranslatePipe,
} from '@placeos/components';
import {
    DateCalendarComponent,
    DateRangeCalendarComponent,
} from '@placeos/form-fields';
import { endOfDay, isSameDay, startOfDay } from 'date-fns';
import {
    bookingTypeCounts,
    SCHEDULE_FILTER_TYPES,
    ScheduleOptions,
    ScheduleStateService,
} from './schedule-state.service';

@Component({
    selector: 'schedule-sidebar',
    template: `
        <div
            class="border-base-300 bg-base-100 flex h-full w-[18rem] flex-col overflow-hidden border-r"
        >
            @if (period === 'day') {
                <date-calendar
                    class="border-base-200 border-b"
                    [ngModel]="date()"
                    (ngModelChange)="setDate($event)"
                    [offset_weekday]="offset_weekday"
                ></date-calendar>
            }
            @if (period === 'week') {
                <div class="w-full p-2">
                    <mat-form-field
                        appearance="outline"
                        class="no-subscript w-full"
                    >
                        <mat-select
                            [ngModel]="week_date()"
                            (ngModelChange)="setDate($event)"
                            [placeholder]="'COMMON.WEEK_SELECT' | translate"
                        >
                            @for (option of week_options(); track option) {
                                <mat-option
                                    [value]="option.id"
                                    class="leading-tight"
                                >
                                    {{ option.name }}
                                    @if (option.this_week) {
                                        <span
                                            class="text-info px-1 text-xs"
                                            [matTooltip]="
                                                'COMMON.WEEK_THIS' | translate
                                            "
                                            >(C)</span
                                        >
                                    }
                                </mat-option>
                            }
                        </mat-select>
                    </mat-form-field>
                </div>
            }
            @if (period === 'list') {
                <date-range-calendar
                    class="border-base-200 border-b p-2"
                    [from]="null"
                    [start]="date()?.valueOf()"
                    [end]="end_date()?.valueOf()"
                    [offset_weekday]="offset_weekday"
                    [max_range_days]="31"
                    (startChange)="setStartDate($event)"
                    (endChange)="setEndDate($event)"
                ></date-range-calendar>
                <div
                    class="bg-info text-info-content m-2 w-[calc(100%-1rem)] rounded p-1 text-center text-xs"
                >
                    {{ 'APP.WORKPLACE.SCHEDULE_RANGE_HINT' | translate }}
                </div>
            }
            <h3 class="mx-4 mt-4 pb-2 font-medium uppercase">
                {{ 'APP.WORKPLACE.SCHEDULE_FILTERS' | translate }}
            </h3>
            <div class="h-1/2 flex-1 space-y-1 overflow-auto px-4">
                @for (item of feature_list; track item.type) {
                    @if (hasFeature(item.feat)) {
                        <settings-toggle
                            [ngModel]="
                                filters()?.shown_types?.includes(item.type)
                            "
                            (click)="toggleType(item.type)"
                        >
                            <div
                                class="-my-2 -ml-2 flex items-center space-x-2"
                            >
                                <div
                                    class="bg-base-300 rounded-full p-1 text-2xl"
                                    [style.background-color]="
                                        colors[item.type][0]
                                    "
                                    [style.color]="colors[item.type][1]"
                                >
                                    <icon>{{ item.icon }}</icon>
                                </div>
                                <div class="flex-1 font-medium">
                                    {{ item.name | translate }}
                                </div>
                                <div class="font-mono text-xs">
                                    {{ counts()[item.type] || 0 }}
                                </div>
                            </div>
                        </settings-toggle>
                    }
                }
                <settings-toggle
                    [ngModel]="filters()?.show_bookings_for_others"
                    (click)="toggleBookingsForOthers()"
                >
                    <div class="-my-2 -ml-2 flex items-center space-x-2">
                        <div class="bg-base-300 rounded-full p-1 text-2xl">
                            <icon>perm_contact_calendar</icon>
                        </div>
                        <div class="flex-1 font-medium">
                            {{
                                'APP.WORKPLACE.SCHEDULE_FILTER_BOOKINGS_FOR_OTHERS'
                                    | translate
                            }}
                        </div>
                        <div class="font-mono text-xs">
                            {{ counts()['bookings-for-others'] || 0 }}
                        </div>
                    </div>
                </settings-toggle>
            </div>
        </div>
    `,
    styles: [
        `
            mat-checkbox {
                pointer-events: none;
            }
        `,
    ],
    imports: [
        CommonModule,
        MatCheckboxModule,
        MatTooltipModule,
        TranslatePipe,
        IconComponent,
        MatRippleModule,
        FormsModule,
        MatFormFieldModule,
        MatSelectModule,
        MatTooltipModule,
        DateCalendarComponent,
        DateRangeCalendarComponent,
        SettingsToggleComponent,
    ],
})
export class ScheduleSidebarComponent extends AsyncHandler implements OnInit {
    private _org = inject(OrganisationService);
    private _state = inject(ScheduleStateService);
    private _settings = inject(SettingsService);

    public readonly filters = this._state.filters;
    public readonly date = computed(() => startOfDay(this._state.date()));
    public readonly end_date = computed(() => {
        const end = this._state.end_date();
        return end ? endOfDay(end) : null;
    });
    public readonly toggleType = (t) => this._state.toggleType(t);
    public readonly toggleBookingsForOthers = () =>
        this._state.toggleBookingsForOthers();
    public readonly hasFeature = (feature: string[]) =>
        this._state.hasFeature(feature);
    public readonly setDate = (d) => this._state.setDate(d);
    public readonly bookings = input<(Booking | CalendarEvent)[]>([]);
    public readonly view = input<'day' | 'week' | 'list'>('day');

    public readonly colors = BOOKING_TYPE_COLORS;

    public readonly week_date = this._state.week_date;
    public readonly week_options = this._state.week_options;

    public readonly feature_list = SCHEDULE_FILTER_TYPES;

    public readonly counts = computed(() => bookingTypeCounts(this.bookings()));

    public get period() {
        const current_view = this.view();
        if (current_view === 'list') return 'list';
        return this._state.getOptions()?.period;
    }

    public setStartDate(date: number) {
        this._state.setDate(date);
        // Clear end date when start date changes
        this._state.setEndDate(null);
    }

    public setEndDate(date: number) {
        this._state.setEndDate(date);
    }

    public get is_today() {
        return isSameDay(this._state.dateValue, Date.now());
    }

    public setDateToToday() {
        this._state.setDate(Date.now());
    }

    public setOptions(options: ScheduleOptions) {
        this._state.setOptions(options);
    }

    public get offset_weekday() {
        return this._settings.get('app.week_start') || 0;
    }

    constructor() {
        super();
        // Show the types that the building features allow. The wait lets the
        // building settings load. The state service applies this one time for
        // each building, so the choices of the user stay between page visits.
        effect((onCleanup) => {
            const bld = this._org.active_building();
            if (!bld) return;
            const timeout = setTimeout(() => {
                this._state.setTypeDefaults(
                    bld.id,
                    Object.fromEntries(
                        SCHEDULE_FILTER_TYPES.map((item) => [
                            item.type,
                            this.hasFeature(item.feat),
                        ]),
                    ),
                );
            }, 1000);
            onCleanup(() => clearTimeout(timeout));
        });
    }

    public ngOnInit() {}
}
